:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #f0f0f0;
  --accent: #f5c542;
  --border: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(-45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--secondary) 75%),
    linear-gradient(-45deg, transparent 75%, var(--secondary) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 6px solid var(--border);
  box-shadow: 8px 8px 0 #0a0a1a;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
  text-shadow: 2px 2px 0 #000;
}

.mode-badge {
  display: inline-block;
  background: var(--secondary);
  border: 3px solid var(--border);
  padding: 4px 16px;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}

.timer {
  font-size: clamp(3.5rem, 18vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--primary);
  margin: 8px 0 24px;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 24px;
  border: 4px solid var(--border);
  background: var(--secondary);
  color: var(--text);
  cursor: pointer;
  box-shadow: 4px 4px 0 #0a0a1a;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
  min-width: 100px;
}

button:hover {
  background: var(--primary);
}

button:focus-visible {
  outline: 4px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

#startPauseBtn {
  background: var(--primary);
}

#startPauseBtn:hover {
  background: var(--accent);
  color: #1a1a2e;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  font-size: 0.85rem;
  padding: 8px 16px;
  min-width: 0;
  opacity: 0.7;
}

.mode-btn.active {
  opacity: 1;
  background: var(--accent);
  color: #1a1a2e;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
    border-width: 4px;
    box-shadow: 6px 6px 0 #0a0a1a;
  }
  .timer {
    letter-spacing: 2px;
  }
  button {
    padding: 10px 16px;
    min-width: 80px;
  }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const timerDisplay = document.getElementById('timerDisplay');
  const modeBadge = document.getElementById('modeBadge');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workModeBtn');
  const breakModeBtn = document.getElementById('breakModeBtn');

  let mode = 'work';
  let totalSeconds = WORK_SECONDS;
  let remaining = WORK_SECONDS;
  let running = false;
  let endTime = 0;
  let intervalId = null;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    timerDisplay.textContent = formatTime(remaining);
    modeBadge.textContent = mode === 'work' ? 'Work' : 'Break';
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
    workModeBtn.classList.toggle('active', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
    workModeBtn.setAttribute('aria-pressed', String(mode === 'work'));
    breakModeBtn.setAttribute('aria-pressed', String(mode === 'break'));
  }

  function stopInterval() {
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  function tick() {
    const now = Date.now();
    const diff = Math.max(0, Math.round((endTime - now) / 1000));
    if (diff !== remaining) {
      remaining = diff;
      render();
    }
    if (remaining <= 0) {
      stopInterval();
      running = false;
      remaining = 0;
      render();
      // Auto-switch mode when timer completes
      if (mode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
    }
  }

  function start() {
    if (running || remaining <= 0) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    intervalId = setInterval(tick, 200);
    render();
  }

  function pause() {
    if (!running) return;
    stopInterval();
    running = false;
    // Update remaining based on actual elapsed time
    const now = Date.now();
    remaining = Math.max(0, Math.round((endTime - now) / 1000));
    render();
  }

  function reset() {
    stopInterval();
    running = false;
    totalSeconds = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    remaining = totalSeconds;
    render();
  }

  function setMode(newMode) {
    stopInterval();
    running = false;
    mode = newMode;
    totalSeconds = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    remaining = totalSeconds;
    render();
  }

  startPauseBtn.addEventListener('click', function () {
    if (running) {
      pause();
    } else {
      start();
    }
  });

  resetBtn.addEventListener('click', reset);

  workModeBtn.addEventListener('click', function () {
    setMode('work');
  });

  breakModeBtn.addEventListener('click', function () {
    setMode('break');
  });

  // Keyboard shortcut: Space toggles start/pause when not focused on a button
  document.addEventListener('keydown', function (e) {
    if (e.code === 'Space' && document.activeElement === document.body) {
      e.preventDefault();
      if (running) {
        pause();
      } else {
        start();
      }
    }
  });

  render();
})();
